(function() {
  const dotInput = document.getElementById('dot-duration');
  const dashInput = document.getElementById('dash-duration');
  const spaceInput = document.getElementById('space-duration');
  const eqDisplay = document.getElementById('eq-display');
  const rootDisplay = document.getElementById('root-display');
  const capacityDisplay = document.getElementById('capacity-display');
  const resetBtn = document.getElementById('reset-params');
  const diagramContainer = document.getElementById('state-diagram');

  function solveCharacteristicEquation(t1, t2, t3) {
    const f = (X) => Math.pow(X, -t1) + Math.pow(X, -t2) + Math.pow(X, -t3) - 1;
    const df = (X) => -t1 * Math.pow(X, -t1 - 1) - t2 * Math.pow(X, -t2 - 1) - t3 * Math.pow(X, -t3 - 1);

    let X = 1.5;
    for (let i = 0; i < 20; i++) {
      const fx = f(X);
      const dfx = df(X);
      if (Math.abs(dfx) < 1e-10) break;
      X = X - fx / dfx;
      if (X <= 1) X = 1.001;
    }
    return X;
  }

  function updateCalculations() {
    const t1 = parseInt(dotInput.value) || 2;
    const t2 = parseInt(dashInput.value) || 4;
    const t3 = parseInt(spaceInput.value) || 5;

    const X0 = solveCharacteristicEquation(t1, t2, t3);
    const C = Math.log2(X0);

    eqDisplay.textContent = `X⁻${t1} + X⁻${t2} + X⁻${t3} = 1`;
    rootDisplay.textContent = X0.toFixed(3);
    capacityDisplay.textContent = `${C.toFixed(3)} bits/unit`;

    renderDiagram();
  }

  function renderDiagram() {
    const svgNS = "http://www.w3.org/2000/svg";
    const svg = document.createElementNS(svgNS, "svg");
    svg.setAttribute("width", "100%");
    svg.setAttribute("height", "150");
    svg.setAttribute("viewBox", "0 0 300 150");

    const circle1 = document.createElementNS(svgNS, "circle");
    circle1.setAttribute("cx", "75");
    circle1.setAttribute("cy", "75");
    circle1.setAttribute("r", "20");
    circle1.setAttribute("fill", "none");
    circle1.setAttribute("stroke", "#1a2b4a");
    circle1.setAttribute("stroke-width", "2");
    svg.appendChild(circle1);

    const text1 = document.createElementNS(svgNS, "text");
    text1.setAttribute("x", "75");
    text1.setAttribute("y", "80");
    text1.setAttribute("text-anchor", "middle");
    text1.setAttribute("font-size", "12");
    text1.setAttribute("fill", "#1a2b4a");
    text1.textContent = "S1";
    svg.appendChild(text1);

    const circle2 = document.createElementNS(svgNS, "circle");
    circle2.setAttribute("cx", "225");
    circle2.setAttribute("cy", "75");
    circle2.setAttribute("r", "20");
    circle2.setAttribute("fill", "none");
    circle2.setAttribute("stroke", "#1a2b4a");
    circle2.setAttribute("stroke-width", "2");
    svg.appendChild(circle2);

    const text2 = document.createElementNS(svgNS, "text");
    text2.setAttribute("x", "225");
    text2.setAttribute("y", "80");
    text2.setAttribute("text-anchor", "middle");
    text2.setAttribute("font-size", "12");
    text2.setAttribute("fill", "#1a2b4a");
    text2.textContent = "S2";
    svg.appendChild(text2);

    const line = document.createElementNS(svgNS, "line");
    line.setAttribute("x1", "95");
    line.setAttribute("y1", "75");
    line.setAttribute("x2", "205");
    line.setAttribute("y2", "75");
    line.setAttribute("stroke", "#007acc");
    line.setAttribute("stroke-width", "2");
    line.setAttribute("marker-end", "url(#arrow)");
    svg.appendChild(line);

    const defs = document.createElementNS(svgNS, "defs");
    const marker = document.createElementNS(svgNS, "marker");
    marker.setAttribute("id", "arrow");
    marker.setAttribute("markerWidth", "10");
    marker.setAttribute("markerHeight", "10");
    marker.setAttribute("refX", "5");
    marker.setAttribute("refY", "5");
    marker.setAttribute("orient", "auto");
    const path = document.createElementNS(svgNS, "path");
    path.setAttribute("d", "M0,0 L10,5 L0,10 z");
    path.setAttribute("fill", "#007acc");
    marker.appendChild(path);
    defs.appendChild(marker);
    svg.insertBefore(defs, svg.firstChild);

    const label = document.createElementNS(svgNS, "text");
    label.setAttribute("x", "150");
    label.setAttribute("y", "60");
    label.setAttribute("text-anchor", "middle");
    label.setAttribute("font-size", "10");
    label.setAttribute("fill", "#6b7280");
    label.textContent = "Transition";
    svg.appendChild(label);

    diagramContainer.innerHTML = '';
    diagramContainer.appendChild(svg);
  }

  dotInput.addEventListener('input', updateCalculations);
  dashInput.addEventListener('input', updateCalculations);
  spaceInput.addEventListener('input', updateCalculations);

  resetBtn.addEventListener('click', () => {
    dotInput.value = 2;
    dashInput.value = 4;
    spaceInput.value = 5;
    updateCalculations();
  });

  updateCalculations();
})();
